+/// Texels the eye draws as material: the composed `max(mesh, cut)` of
+/// the packed lattice is below zero.
+fn solid(mesh: &[f32], cut: &[f32]) -> usize {
+    mesh.iter().zip(cut).filter(|(m, c)| m.max(**c) < 0.0).count()
+}
